/**
 * Environment dressing: everything visible in the world is a model from the free
 * CC0 packs in Worlds_Edge_Free_3D_Environment_Packs.pdf. The world layout
 * (world.ts) places terrain tiles and set pieces; this module scatters each
 * area's props (one pack per island), deterministically so the server and
 * every client agree on where things are.
 *
 * Model sizes and height profiles come from `env-models.ts`, generated by
 * `npm run build-env`. Solid models get invisible box colliders: one box
 * ("full"), a thin trunk ("trunk"), or a stepped shape that follows the model's
 * height profile ("shape": roofs, towers, mountains).
 */
import { SEA_LEVEL } from "./constants.ts";
import { ENV_MODELS, ENV_PROFILE } from "./env-models.ts";
import { CATALOGUE, cave, ck, dk, kd, kh, nk, pk, wk } from "./catalogue.ts";
import type { Box, Region } from "./world.ts";

export interface Placement {
  /** "<pack>/<model>" — the client loads /env/<pack>/<model>.glb */
  model: string;
  /** Where the model's origin goes. */
  x: number; y: number; z: number;
  rotY: number;
  /** Scale per axis (most models are uniform; terrain columns stretch in y). */
  sx: number; sy: number; sz: number;
  collide?: Collide;
}

export type Collide = "full" | "trunk" | "shape";

export interface DressedArea {
  id: string;
  name: string;
  /** The pack actually used for the props (the area's own, or its stand-in). */
  pack: string;
  /** The pack this area is meant to use. */
  plannedPack: string;
  center: { x: number; y: number; z: number };
  /** Load the area's models when the camera is within this distance of `center`. */
  loadRadius: number;
  /** Terrain, buildings and landmarks: loaded at start and always drawn. */
  always?: boolean;
  placements: Placement[];
}

// --- Placing single models ----------------------------------------------------------------

const cosSin = (rotY: number) => [Math.cos(rotY), Math.sin(rotY)] as const;

/** Model-space (x, z) → world, for a model placed at `p` (Babylon's y-rotation). */
function toWorld(p: Placement, lx: number, lz: number): [number, number] {
  const [c, s] = cosSin(p.rotY);
  const x = lx * p.sx, z = lz * p.sz;
  return [p.x + x * c + z * s, p.z - x * s + z * c];
}

/**
 * Place a model uniformly scaled so its footprint's centre lands on (x, z) and its
 * base sits on `groundY`. Returns null when the model isn't built.
 */
export function place(model: string, x: number, groundY: number, z: number, rotY: number, scale: number, collide?: Collide): Placement | null {
  const info = ENV_MODELS[model];
  if (!info) return null;
  const cx = ((info.min[0] + info.max[0]) / 2) * scale, cz = ((info.min[2] + info.max[2]) / 2) * scale;
  const [c, s] = cosSin(rotY);
  return {
    model,
    x: x - (cx * c + cz * s), y: groundY - info.min[1] * scale, z: z - (-cx * s + cz * c),
    rotY, sx: scale, sy: scale, sz: scale,
    ...(collide ? { collide } : {}),
  };
}

/** Size of a model in metres at a scale: [width (x), height, depth (z)]. */
export function modelSize(model: string, scale = 1): [number, number, number] {
  const info = ENV_MODELS[model];
  if (!info) return [0, 0, 0];
  return [0, 1, 2].map((k) => (info.max[k] - info.min[k]) * scale) as [number, number, number];
}

/** Stretch a model onto an axis-aligned block (stairs, decks): any scale per axis. */
export function fitToBlock(model: string, minX: number, minY: number, minZ: number, maxX: number, maxY: number, maxZ: number, rotY = 0): Placement | null {
  const info = ENV_MODELS[model];
  if (!info) return null;
  const quarter = Math.round(rotY / (Math.PI / 2)) & 1;
  const [w, h, d] = [maxX - minX, maxY - minY, maxZ - minZ];
  const [mw, mh, md] = [0, 1, 2].map((k) => Math.max(1e-3, info.max[k] - info.min[k]));
  const sx = (quarter ? d : w) / mw, sz = (quarter ? w : d) / md, sy = h / mh;
  const p: Placement = { model, x: 0, y: minY - info.min[1] * sy, z: 0, rotY, sx, sy, sz };
  // Put the rotated model's centre on the block's centre.
  const [cx, cz] = toWorld(p, (info.min[0] + info.max[0]) / 2, (info.min[2] + info.max[2]) / 2);
  p.x = (minX + maxX) / 2 - cx;
  p.z = (minZ + maxZ) / 2 - cz;
  return p;
}

function hiddenBox(minX: number, minY: number, minZ: number, maxX: number, maxY: number, maxZ: number, region: Region): Box {
  return { minX, minY, minZ, maxX, maxY, maxZ, color: "#000000", region, hidden: true };
}

/** World-space bounding rectangle of a model-space rectangle under the placement. */
function rectToWorld(p: Placement, x0: number, z0: number, x1: number, z1: number) {
  const pts = [toWorld(p, x0, z0), toWorld(p, x1, z0), toWorld(p, x0, z1), toWorld(p, x1, z1)];
  return {
    minX: Math.min(...pts.map((q) => q[0])), maxX: Math.max(...pts.map((q) => q[0])),
    minZ: Math.min(...pts.map((q) => q[1])), maxZ: Math.max(...pts.map((q) => q[1])),
  };
}

/** Invisible colliders for a solid placement. */
export function collidersFor(p: Placement, region: Region = "isles"): Box[] {
  const info = ENV_MODELS[p.model];
  if (!p.collide || !info) return [];
  const base = p.y + info.min[1] * p.sy;
  const height = (info.max[1] - info.min[1]) * p.sy;
  if (p.collide === "trunk") {
    const [w, , d] = modelSize(p.model, p.sx);
    const t = Math.max(0.5, Math.min(w, d) * 0.16);
    const [cx, cz] = toWorld(p, (info.min[0] + info.max[0]) / 2, (info.min[2] + info.max[2]) / 2);
    return [hiddenBox(cx - t / 2, base, cz - t / 2, cx + t / 2, base + height * 0.75, cz + t / 2, region)];
  }
  if (p.collide === "full") {
    const r = rectToWorld(p, info.min[0], info.min[2], info.max[0], info.max[2]);
    return [hiddenBox(r.minX, base, r.minZ, r.maxX, base + height, r.maxZ, region)];
  }
  // "shape": a column per height-profile cell, merged along rows of equal height.
  const n = ENV_PROFILE;
  const w = (info.max[0] - info.min[0]) / n, d = (info.max[2] - info.min[2]) / n;
  const out: Box[] = [];
  for (let cz = 0; cz < n; cz++) {
    let cx = 0;
    while (cx < n) {
      const h = info.cols[cz * n + cx];
      let end = cx + 1;
      while (end < n && Math.abs(info.cols[cz * n + end] - h) < 0.02) end++;
      if (h > 0.03) {
        const r = rectToWorld(p, info.min[0] + cx * w, info.min[2] + cz * d, info.min[0] + end * w, info.min[2] + (cz + 1) * d);
        out.push(hiddenBox(r.minX, base, r.minZ, r.maxX, base + h * height, r.maxZ, region));
      }
      cx = end;
    }
  }
  return out;
}

// --- Prop scatter per area -----------------------------------------------------------

/** top: anywhere on the walkable surface · edge: on it, near a drop · shore: in the shallows · water: open sea */
type Where = "top" | "edge" | "shore" | "water";

interface Group {
  models: string[];
  count: number;
  /** Target size in metres (scaled uniformly): its height, or with fit "longest" its longest side. */
  height: [number, number];
  fit?: "longest";
  collide?: Collide;
  where?: Where;
  /** Minimum distance to other placements (metres). */
  spacing?: number;
  /** Turn freely (default), or only in quarter turns (needed for exact box colliders). */
  quarter?: boolean;
}

/** Where an area's props may go: a disc (isles) or a rectangle, at a walkable height. */
interface Surface { x: number; z: number; r?: number; hx?: number; hz?: number; y: number }

interface AreaSpec {
  id: string;
  name: string;
  pack: string;
  surface: Surface;
  /** For shore and water placements: how far out from the surface's edge to go. */
  waterReach?: number;
  groups: Group[];
  /** Used when `pack` hasn't been downloaded yet (Google Drive quota, itch.io). */
  standIn?: { pack: string; groups: Group[] };
}

