function blocked(base: Box[], x: number, y: number, z: number, margin: number) {
  for (const b of base) {
    if (b.minY <= y + 0.05 && b.maxY > y + 0.05 && x > b.minX - margin && x < b.maxX + margin && z > b.minZ - margin && z < b.maxZ + margin) return true;
  }
  return false;
}

function groundAt(base: Box[], x: number, z: number, fromY: number) {
  let best = -Infinity;
  for (const b of base) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.maxY <= fromY + 0.01 && b.maxY > best) best = b.maxY;
  }
  return best;
}

export function packAvailable(pack: string) {
  for (const id in ENV_MODELS) if (id.startsWith(`${pack}/`)) return true;
  return false;
}

function layout(spec: AreaSpec, base: Box[]): DressedArea {
  const own = packAvailable(spec.pack);
  const pack = own || !spec.standIn ? spec.pack : spec.standIn.pack;
  const groups = own || !spec.standIn ? spec.groups : spec.standIn.groups;
  const r = rng(hash(spec.id));
  const placed: Placement[] = [];
  const s = spec.surface;
  const extent = s.r ?? Math.max(s.hx ?? 0, s.hz ?? 0);
  const inside = (x: number, z: number) => (s.r ? Math.hypot(x - s.x, z - s.z) <= s.r : Math.abs(x - s.x) <= s.hx! && Math.abs(z - s.z) <= s.hz!);

  for (const g of groups) {
    const models = g.models.filter((m) => ENV_MODELS[m]);
    if (!models.length) continue;
    const where = g.where ?? "top";
    let made = 0;
    for (let attempt = 0; attempt < g.count * 30 && made < g.count; attempt++) {
      let x: number, z: number, y: number;
      if (where === "top" || where === "edge") {
        x = s.x + (r() * 2 - 1) * (s.r ?? s.hx! + 12);
        z = s.z + (r() * 2 - 1) * (s.r ?? s.hz! + 12);
        if (where === "top" && !inside(x, z)) continue;
        y = groundAt(base, x, z, s.y + 0.5);
        if (Math.abs(y - s.y) > 0.6 || blocked(base, x, y, z, 1.2)) continue;
        if (where === "edge" && ![[9, 0], [-9, 0], [0, 9], [0, -9]].some(([dx, dz]) => groundAt(base, x + dx, z + dz, s.y + 0.5) < s.y - 1)) continue;
      } else if (where === "shore") {
        // Just off the land's edge, standing in the shallows.
        const a = r() * Math.PI * 2;
        let d = extent * 0.5;
        // Walk outward until there's no land under us.
        while (d < extent + 40 && groundAt(base, s.x + Math.cos(a) * d, s.z + Math.sin(a) * d, 300) > SEA_LEVEL - 1) d += 2;
        d += 1 + r() * 4;
        x = s.x + Math.cos(a) * d; z = s.z + Math.sin(a) * d;
        y = SEA_LEVEL - 1.5;
        if (blocked(base, x, y + 2, z, 0.5)) continue;
      } else {
        // Open water near the area.
        const a = r() * Math.PI * 2, d = s.r ? s.r + 10 + r() * (spec.waterReach ?? 20) : 0;
        x = s.r ? s.x + Math.cos(a) * d : s.x + (r() * 2 - 1) * s.hx!;
        z = s.r ? s.z + Math.sin(a) * d : s.z + (r() * 2 - 1) * s.hz!;
        y = SEA_LEVEL - 0.2;
        if (groundAt(base, x, z, 300) > -50 || blocked(base, x, y + 0.5, z, 8)) continue;
      }
      if (KEEP_CLEAR.some((k) => Math.hypot(x - k.x, z - k.z) < k.r)) continue;
      const spacing = g.spacing ?? 3;
      if (placed.some((p) => Math.hypot(p.x - x, p.z - z) < spacing)) continue;
      const model = models[Math.floor(r() * models.length)];
      const info = ENV_MODELS[model];
      const height = g.height[0] + r() * (g.height[1] - g.height[0]);
      const dims = [0, 1, 2].map((k) => info.max[k] - info.min[k]);
      const scale = height / Math.max(0.01, g.fit === "longest" ? Math.max(...dims) : dims[1]);
      const quarter = g.quarter || g.collide === "full";
      const rotY = quarter ? Math.floor(r() * 4) * (Math.PI / 2) : r() * Math.PI * 2;
      const p = place(model, x, y, z, rotY, scale, g.collide);
      if (p) { placed.push(p); made++; }
    }
  }

  return {
    id: spec.id, name: spec.name, pack, plannedPack: spec.pack,
    center: { x: s.x, y: s.y, z: s.z },
    loadRadius: extent + 650,
    placements: placed,
  };
}

let cachedAreas: DressedArea[] | undefined;

/** Scatter every overworld area's props (not the arena) over the world's solid boxes. */
export function dressOverworld(base: Box[]): { areas: DressedArea[]; colliders: Box[] } {
  const props = AREAS.filter((a) => a.id !== "arena").map((a) => layout(a, base));
  cachedAreas = props;
  return { areas: props, colliders: props.flatMap((a) => a.placements.flatMap((p) => collidersFor(p))) };
}

/** The arena's decorative ruins (the fight's geometry stays as tuned). */
export function dressArena(base: Box[]): DressedArea {
  return layout(AREAS.find((a) => a.id === "arena")!, base);
}

export function overworldAreas(): DressedArea[] {
  return cachedAreas ?? [];
}

/** Every model id the world may use (the asset build converts these). */
export function allDressingModels(): string[] {
  const ids = new Set<string>(CATALOGUE);
  for (const a of AREAS) {
    for (const g of a.groups) g.models.forEach((m) => ids.add(m));
    for (const g of a.standIn?.groups ?? []) g.models.forEach((m) => ids.add(m));
  }
  return [...ids].sort();
}

export const AREA_PACKS = AREAS.map((a) => ({ id: a.id, name: a.name, pack: a.pack, standIn: a.standIn?.pack ?? null }));
